mapper.insert:
INSERT INTO analysis_runs (
    user_id, period_start, period_end, trade_count, journal_count, analysis_version
) VALUES (
    #{userId}, #{periodStart}, #{periodEnd}, #{tradeCount}, #{journalCount}, #{analysisVersion}
)

mapper.select:
SELECT analysis_run_id, user_id, period_start, period_end, trade_count, journal_count, analysis_version, created_at
FROM analysis_runs
WHERE analysis_run_id = #{analysisRunId}
  AND user_id = #{userId}
